(* MemoryStorage<Dst> *)
memory_storage_1_term = (dst_term, ".", "$mem" | "(", memory_storage_1_term, ")") ;
(* MemoryStorage<Src> *)
memory_storage_2_term = (src_term, ".", "$mem" | "(", memory_storage_2_term, ")") ;
