(* MemoryStorage<Int> *)
memory_storage_1_term = (int_term, ".", "$mem" | "(", memory_storage_1_term, ")") ;
(* MemoryStorage<f16> *)
memory_storage_2_term = (f16_term, ".", "$mem" | "(", memory_storage_2_term, ")") ;
