(* MemoryStorage<(*mut [T], *mut [T])> *)
memory_storage_1_term = (tuple_term, ".", "$mem" | "(", memory_storage_1_term, ")") ;
(* MemoryStorage<*mut [T]> *)
memory_storage_2_term = (pointer_term, ".", "$mem" | "(", memory_storage_2_term, ")") ;
(* MemoryStorage<usize> *)
memory_storage_3_term = (usize_term, ".", "$mem" | "(", memory_storage_3_term, ")") ;
(* MemoryString *)
