memory_storage_1_term = (idx_term, ".", "$mem" | "(", memory_storage_1_term, ")") ;
(* MemoryStorage<T> *)
memory_storage_2_term = (t_term, ".", "$mem" | "(", memory_storage_2_term, ")") ;
(* MemoryStorage<[T]> *)
memory_storage_3_term = (sequence_term, ".", "$mem" | "(", memory_storage_3_term, ")") ;
(* MemoryStorage<core::ops::range::Range<Idx>> *)
memory_storage_4_term = (range_term, ".", "$mem" | "(", memory_storage_4_term, ")") ;
(* MemoryString *)
memory_string_term = (memory_allocation_term, ".", "id" | memory_allocation_term, ".", "allocator" | "(", memory_string_term, ")") ;
